import java.util.ArrayList;
import java.util.List;

public final class Solution {
    private Solution() {}

    public static final class Announcement {
        private final String heading;
        private final String body;
        private final int sequence;

        public Announcement(String heading, String body, int sequence) {
            if (heading == null || heading.isBlank()
                    || body == null || body.isBlank() || sequence < 0) {
                throw new IllegalArgumentException("Invalid announcement");
            }
            this.heading = heading.trim();
            this.body = body.trim();
            this.sequence = sequence;
        }

        public String getHeading() { return heading; }
        public String getBody() { return body; }
        public int getSequence() { return sequence; }
    }

    public interface AnnouncementListener {
        void onAnnouncement(Announcement announcement);
    }

    public static final class AnnouncementHub {
        private final List<AnnouncementListener> listeners = new ArrayList<>();

        private AnnouncementHub() {}
    }

    public static AnnouncementHub newHub() {
        return new AnnouncementHub();
    }

    public static void subscribe(AnnouncementHub hub,
                                 AnnouncementListener listener) {
        validate(hub, listener);
        for (AnnouncementListener existing : hub.listeners) {
            if (existing == listener) {
                return;
            }
        }
        hub.listeners.add(listener);
    }

    public static boolean unsubscribe(AnnouncementHub hub,
                                      AnnouncementListener listener) {
        validate(hub, listener);
        for (int i = 0; i < hub.listeners.size(); i++) {
            if (hub.listeners.get(i) == listener) {
                hub.listeners.remove(i);
                return true;
            }
        }
        return false;
    }

    public static void publish(AnnouncementHub hub,
                               Announcement announcement) {
        if (hub == null || announcement == null) {
            throw new IllegalArgumentException("Null argument");
        }
        List<AnnouncementListener> snapshot = new ArrayList<>(hub.listeners);
        for (AnnouncementListener listener : snapshot) {
            listener.onAnnouncement(announcement);
        }
    }

    private static void validate(AnnouncementHub hub,
                                 AnnouncementListener listener) {
        if (hub == null || listener == null) {
            throw new IllegalArgumentException("Null argument");
        }
    }
}
